export function problem(message,status=400){return Object.assign(new Error(message),{status})}
export function validate(q){if(!q||typeof q!=='object'||Array.isArray(q))throw problem('Object required');const allowed=['name','type','country','birthDate','provider','mode'];if(Object.keys(q).some(k=>!allowed.includes(k)))throw problem('Unknown input field');if(typeof q.name!=='string'||q.name.trim().length<2||q.name.length>160||/[\x00-\x1f]/.test(q.name))throw problem('Name must contain 2–160 characters');const type={Person:'person',Company:'company',person:'person',company:'company'}[q.type];if(!type)throw problem('Type must be person or company');if(q.country&&(typeof q.country!=='string'||!/^[a-z]{2}$/i.test(q.country)))throw problem('Country must be a two-letter code');if(q.birthDate&&(type!=='person'||typeof q.birthDate!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(q.birthDate)||!Number.isFinite(Date.parse(q.birthDate))||new Date(q.birthDate).toISOString().slice(0,10)!==q.birthDate||q.birthDate>new Date().toISOString().slice(0,10)))throw problem('Invalid birth date');if(q.provider&&!['csl','opensanctions'].includes(q.provider))throw problem('Unsupported provider');if(q.mode&&!['demo','live'].includes(q.mode))throw problem('Mode must be demo or live');return {name:q.name.trim(),type,country:q.country?.toUpperCase()||'',birthDate:q.birthDate||'',provider:q.provider||'csl',mode:q.mode||'live'}}
